1:  .command("run")
2:  .description("Run an autonomous coding task")
3:  .argument("[prompt...]", "The coding instructions / task prompt")
4:  .option("-e, --endpoint <url>", "Local LLM endpoint (default: http://localhost:1234/v1 or $LOCAL_LLM_ENDPOINT)")
5:  .option("-m, --model <name>", "Model name identifier (default: active model in LM Studio/vLLM)")
6:  .option("-w, --workspace <path>", "Workspace directory to inspect and modify (default: current directory)")
7:  .option("-s, --max-steps <number>", "Steps per segment; continuation checkpoints there instead of stopping", "30")
8:  .option("--max-total-steps <number>", "Continuation: objective-wide step limit shared across resumes (default: 500)")
9:  .option("--strict-token-count", "Refuse a request the connection could not count on a worker (default: proceed on the labelled estimate)")
10:  .option("--max-turn-minutes <number>", "Continuation: active invocation wall-clock limit in minutes (default: 480)")
11:  .option("--stagnation-steps <number>", "Continuation: stop after this many steps without progress (default 12)")
12:  .option("--no-continuation", "End a turn at --max-steps instead of continuing while it makes progress")
13:  .option("-t, --temperature <number>", "Model temperature", "0.2")
14:  .option("--shell <type>", "Linux shell to use: bash, zsh, or sh (default: bash or $LOCAL_HARNESS_SHELL)", "bash")
15:  .option("--fallback <urls>", "Comma-separated fallback LLM endpoints if primary is unavailable")
16:  .option("--context-limit <tokens>", "Context window limit in tokens; below the provider's advertised capacity it is kept, above it the advertised capacity applies (default: advertised capacity, else 65536)")
17:  .option("--dry-run", "Simulate file modifications without writing changes to disk")
18:  .option("--read-only", "Reject all mutating tool executions and commands")
19:  .option("-y, --yes", "Run non-interactively without approval prompts (forces auto mode)")
20:  .option("--approve", "Require human approval before destructive actions (forces review mode)")
21:  .option("--mode <mode>", "Execution mode: auto, review, or read-only (default: review; folder trust does not change it)")
22:  .option("--sandbox [mode]", "Isolate command execution using bubblewrap (bwrap) or Docker (default: auto)")
23:  .option("--sandbox-network", "With --sandbox: let sandboxed commands and the sandboxed native worker use the network (off by default; also NEXUS_SANDBOX_NETWORK=1 in the operator environment)")
24:  .option("--worktree", "Isolate execution inside an ephemeral git worktree under .nexus/worktrees/<task-id>")
25:  .option("--worktree-branch <name>", "Run inside the named git worktree for this branch (created if missing); kept after the run, merge it with `nexus worktree merge`")
26:  .option("--authoritative-verifier <command>", "Trusted command that must pass before any task completion; its success may authorize automatic worktree merge")
27:  .option("--deliverable-file <path>", "Operator-declared workspace-relative product file used for VERIFIED binding (repeatable)", collectDeliverableFile, [])
28:  .option("--record-flight", "Record execution into an append-only deterministic .flightlog")
29:  .option("--planner-model <name>", "Deep reasoning model for architecture planning (o3, R1, Sonnet)")
30:  .option("--planner-endpoint <url>", "Dedicated inference endpoint for planner model")
31:  .option("--coder-model <name>", "High-throughput model for surgical code implementation (Qwen 2.5 Coder)")
32:  .option("--coder-endpoint <url>", "Dedicated inference endpoint for coder model")
33:  .option("--tdd", "Enforce strict RED-GREEN-REFACTOR Test-Driven Development protocol")
34:  .option("--provider <id>", "Cloud inference provider: openrouter, openai, anthropic, compatible (default: appliance endpoint)")
35:  .option("--base-url <url>", "Override the provider's base URL (operator-only; required for 'compatible')")
36:  .option("--planner-provider <id>", "Cloud provider for the planner model (requires --planner-model)")
37:  .option("--coder-provider <id>", "Cloud provider for the coder model (requires --coder-model)")
38:  .option("-j, --json", "Output machine-readable JSON structured result (UI-002, UI-003)")
39:  .option("--output <format>", "Output format: text (default), json (same as --json) or stream-json (one JSON event per line, nothing else on stdout; see docs/STREAM_JSON.md)")
40:  .option("-r, --resume [id]", "Resume previous session or task state")
41:  .option("--fork-session <id>", "Start in a new copy of the named session (the original is never changed; prints the new id)")
42:  .option("--fork-at <n>", "With --fork-session: copy only the first n messages (default: all)")
43:  .option("--answer <id=approve|decline>", "With --resume: answer a question the blocked run asked (the 12-character needsInput.id in its result); for a question that asks for a reply (a blocked requirement), <id>=reply:<text>; repeatable", collectAnswer, [])
44:  .option("--step", "Execute one model/tool cycle and pause deterministically")
45:  .action(async (promptParts: string[], _options: any, cmd: Command) => {
46:    const options = commandOptions(cmd);
47:    let prompt = promptParts.join(" ").trim();
48:    const config = buildConfig(options);
49:    config.surface = "headless";
50:    let answers: ReturnType<typeof parseOperatorAnswers> | undefined;
51:    if ((options.answer ?? []).length) {
52:      try {
53:        if (options.resume === undefined || options.resume === false) throw new Error("--answer needs --resume (it answers a question a blocked run asked)");
54:        answers = parseOperatorAnswers(options.answer);
55:      } catch (err: any) {
56:        console.error(`error: ${err.message}`);
57:        exitAfterFlush(2);
58:        return;
59:      }
60:    }
61:    const forkError = forkStartError(options);
62:    if (forkError) {
63:      console.error(`error: ${forkError}`);
64:      exitAfterFlush(2);
65:      return;
66:    }
67:    const outputFormat = String(options.output ?? (options.json ? "json" : "text"));
68:    if (!["text", "json", "stream-json"].includes(outputFormat) || (options.json && outputFormat !== "json")) {
69:      console.error(options.json && ["text", "stream-json"].includes(outputFormat) ? "error: --json cannot be combined with --output " + outputFormat : "error: --output must be text, json or stream-json");
70:      exitAfterFlush(2);
71:      return;
72:    }
73:    const isStream = outputFormat === "stream-json";
74:    // The event sink writes through the real stdout.write, captured before runTask intercepts stdout for machine output.
75:    const realStdoutWrite = process.stdout.write.bind(process.stdout);
76:    const emitEvent = isStream ? streamEventSink((chunk) => realStdoutWrite(chunk)) : undefined;
77:    const isJson = outputFormat !== "text";
78:
79:    // Auto-detect loaded model if model is 'local-model' (not on a resume: the task record supplies it, or the first
80:    // step detects it after the resumed provider wait)
81:    if (config.model === "local-model" && (options.resume === undefined || options.resume === false) && options.forkSession === undefined) {
82:      try {
83:        const client = new LocalLlmClient(config);
84:        const models = await client.listModels();
85:        if (models.length > 0) {
86:          config.model = models[0];
87:          if (!isJson) {
88:            console.log(pc.dim(`🔍 Auto-detected active model: ${pc.bold(config.model)}`));
89:          }
90:        }
91:      } catch {
92:        // Fallback to default
93:      }
94:    }
95:
96:    if (!isJson && (config.provider || config.plannerProvider || config.coderProvider)) console.error(pc.dim(describeTarget(config)));
97:    const app = new ApplicationCore(config);
98:
99:    if (options.forkSession !== undefined) {
100:      try {
101:        // `run --resume` reads the task store, so the fork is made there (the source is a task id, as for --resume).
102:        const forked = startFork(new SessionManager(app.getStateManager().getBaseDir(), () => app.getAgent().getWorkspacePathIdentity()), options);
