    try {
      text = await readBounded(fs.createReadStream(source.inputJson), "--input-json: the input");
    } catch (err: any) {
      if (!err?.code) throw err;
      throw new Error(`--input-json: cannot read ${source.inputJson} (${err.code})`);
    }
