    { mode: 0o600 },
  );
}

export async function waitUntil(cond: () => boolean, timeoutMs = 10000): Promise<void> {
  const deadline = Date.now() + timeoutMs;
/**
 * Leak and hang guard: `import "./helpers/leak_guard.js";` at the top of a test file fails the file in teardown, naming
 * every RustCoreBridge or AutonomousAgent not shut down, scripted gateway not closed, child process still running and
 * timer still pending, then releases them so the process can exit instead of hanging the job.
 * Resources it cannot see by itself (a custom server) can be registered with `trackResource`.
 * Timers: ref'd timeouts above the count when the file finished loading (a timer created while the file loads is not
 * counted; node:test's own timers are gone by teardown). The check hook is registered once the file has finished
 * loading, so it runs after the file's own `after` hooks; a file that registers hooks after a top-level `await` can run
 * its hooks after the guard's check, and should then release in the test itself.
 */
import { after } from "node:test";
import childProcess from "node:child_process";
import { RustCoreBridge } from "../../src/tools.js";
import { survivors, trackResource, clearTracked } from "./leak_registry.js";

export { trackResource };

const proto = childProcess.ChildProcess.prototype as any;
const originalSpawn = proto.spawn;
proto.spawn = function (this: childProcess.ChildProcess, ...args: unknown[]) {
  const result = originalSpawn.apply(this, args);
  const command = [String((this as any).spawnfile ?? ""), ...((this as any).spawnargs ?? []).slice(1)].join(" ").slice(0, 120);
  trackResource("child process", `pid ${this.pid} ${command}`, () => this.exitCode === null && this.signalCode === null, () => {
    try { process.kill(-(this.pid as number), "SIGKILL"); } catch { this.kill("SIGKILL"); }
  });
  return result;
};

let baselineTimers = 0;
function activeTimers(): number {
// Shrink-only ratchet for the test leak guard. A test file that constructs a RustCoreBridge, an AutonomousAgent or a
// scripted gateway (startGateway) must import test/helpers/leak_guard, unless it is listed in
// test/leak_guard_baseline.json. A file not on the baseline that skips the guard fails, and so does a baseline entry whose
// file has adopted the guard or no longer constructs any of them (remove it). Run directly (exit 1) or import checkLeaks.
// `--write-baseline` rewrites the list (only ever to shrink it in review).
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";

const constructs = /new\s+(?:RustCoreBridge|AutonomousAgent)\s*\(|(?<!function\s)\bstartGateway\s*\(/;
const guarded = /\bleak_guard(?:\.js|\.ts)?["']/;
const ignored = new Set(["leak_guard.test.ts", "leak_guard.ts", "leak_registry.ts"]);

function sources(dir, base = dir) {
  return fs.readdirSync(dir, { withFileTypes: true }).flatMap((entry) => {
    const full = path.join(dir, entry.name);
    if (entry.isDirectory()) return sources(full, base);
    return /\.(?:ts|mjs)$/.test(entry.name) && !ignored.has(entry.name) ? [path.relative(base, full)] : [];
  });
}

export function checkLeaks(testDir, baselineFile) {
  const baseline = new Set(JSON.parse(fs.readFileSync(baselineFile, "utf8")));
  const files = sources(testDir);
  const text = (f) => fs.readFileSync(path.join(testDir, f), "utf8");
  const building = files.filter((f) => constructs.test(text(f)));
  const unguarded = building.filter((f) => !guarded.test(text(f))).sort();
  return {
    unguarded,
    missing: unguarded.filter((f) => !baseline.has(f)),
    stale: [...baseline].filter((f) => !unguarded.includes(f)).sort(),
  };
}

if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  const dir = path.resolve(path.dirname(fileURLToPath(import.meta.url)), "../test");
  const baselineFile = path.join(dir, "leak_guard_baseline.json");
  if (process.argv.includes("--write-baseline")) {
    if (!fs.existsSync(baselineFile)) fs.writeFileSync(baselineFile, "[]\n");
    fs.writeFileSync(baselineFile, `${JSON.stringify(checkLeaks(dir, baselineFile).unguarded, null, 2)}\n`);

