  const c = spawn(process.execPath, ["--import", "tsx", "src/index.ts", "run", "-e", gw.url, "-m", "m", "-w", repo, "-y", "--json", "write x.txt"], { cwd: CLI, env: { ...env, HOME: home, XDG_CONFIG_HOME: path.join(home, ".config"), XDG_DATA_HOME: path.join(home, ".local/share"), XDG_STATE_HOME: path.join(home, ".local/state"), XDG_CACHE_HOME: path.join(home, ".cache") }, stdio: ["ignore", "pipe", "ignore"] });
